// Overengineering-O-Matic — comedy simulation demo (FICTION: not real, for laughs only)
var BONKERS_NAME = "Overengineering-O-Matic";
var BONKERS_BITS = ["takes", "simple", "generates", "comically", "overcomplicated", "solution", "possible", "overengineering", "matic"];
function bonkersPrng(seed){ var s = seed >>> 0; return function(){ s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; }
function bonkersRun(seed){
  var rnd = bonkersPrng(seed);
  function pick(a){ return a[Math.floor(rnd() * a.length)]; }
  var chaos = (Math.floor(rnd() * 900) + 100) / 10;
  var widgets = Math.floor(rnd() * 9999) + 1;
  var line = 'Unit ' + widgets + ': ' + pick(BONKERS_BITS) + ' collided with ' + pick(BONKERS_BITS) + ' during routine ' + pick(BONKERS_BITS) + ' maintenance.';
  return { fiction: 'FICTION - comedy concept, not real', simulator: BONKERS_NAME, seed: seed, event: line, chaos_index: chaos, widgets_deployed: widgets };
}
console.log(JSON.stringify(bonkersRun(79100)));

